def _setup(client):
    user = client.post("/users", json={"username": "dev", "email": "dev@example.com"}).json()
    project = client.post("/projects", json={"name": "Mercury", "owner_id": user["id"]}).json()
    return user, project


def test_capacity_enforced_on_create(client):
    user, project = _setup(client)
    for i in range(3):
        resp = client.post(
            "/tasks",
            json={"title": f"T{i}", "project_id": project["id"], "assignee_id": user["id"]},
        )
        assert resp.status_code == 201, resp.text

    resp = client.post(
        "/tasks",
        json={"title": "overflow", "project_id": project["id"], "assignee_id": user["id"]},
    )
    assert resp.status_code == 409, resp.text


def test_capacity_enforced_on_reassignment(client):
    user, project = _setup(client)
    for i in range(3):
        client.post(
            "/tasks",
            json={"title": f"T{i}", "project_id": project["id"], "assignee_id": user["id"]},
        )
    unassigned = client.post(
        "/tasks", json={"title": "free", "project_id": project["id"]}
    ).json()

    resp = client.patch(f"/tasks/{unassigned['id']}", json={"assignee_id": user["id"]})
    assert resp.status_code == 409, resp.text


def test_completed_tasks_dont_count_against_capacity(client):
    user, project = _setup(client)
    tasks = []
    for i in range(3):
        t = client.post(
            "/tasks",
            json={"title": f"T{i}", "project_id": project["id"], "assignee_id": user["id"]},
        ).json()
        tasks.append(t)
    client.patch(f"/tasks/{tasks[0]['id']}", json={"status": "done"})

    resp = client.post(
        "/tasks",
        json={"title": "room now", "project_id": project["id"], "assignee_id": user["id"]},
    )
    assert resp.status_code == 201, resp.text


